window.__votdWeek && window.__votdWeek({"week":"2028-02-21","reading":"2 Nephi 11–19","days":[{"d":"2028-02-21","ref":"2 Nephi 12:2","b":"2 Nephi","c":12,"v":2,"he":"וְהָיָה בְּאַחֲרִית הַיָּמִים נָכוֹן יִהְיֶה הַר בֵּית־יְהוָה בְּרֹאשׁ הֶהָרִים וְנִשָּׂא מִגְּבָעוֹת וְנָהֲרוּ אֵלָיו כׇּל־הַגּוֹיִם׃","en":"And it shall come to pass in the last days, when the mountain of the Lord’s house shall be established in the top of the mountains, and shall be exalted above the hills, and all nations shall flow unto it."},{"d":"2028-02-22","ref":"2 Nephi 12:12","b":"2 Nephi","c":12,"v":12,"he":"כִּי יוֹם לַיהוָה צְבָאוֹת בָּא מְהֵרָה עַל כׇּל־הַגּוֹיִם אַף עַל כׇּל־אֶחָד אַף עַל הַגֵּאֶה וְהָרָם וְעַל כׇּל־נִשָּׂא וְשָׁפֵל׃","en":"For the day of the Lord of Hosts soon cometh upon all nations, yea, upon every one; yea, upon the proud and lofty, and upon every one who is lifted up, and he shall be brought low."},{"d":"2028-02-23","ref":"2 Nephi 13:8","b":"2 Nephi","c":13,"v":8,"he":"כִּי כָשְׁלָה יְרוּשָׁלַיִם וִיהוּדָה נָפָל כִּי־לְשׁוֹנוֹתָם וּמַעַלְלֵיהֶם אֶל־יְהוָה לַמְרוֹת עֵנֵי כְבוֹדוֹ׃","en":"For Jerusalem is ruined, and Judah is fallen, because their tongues and their doings have been against the Lord, to provoke the eyes of his glory."},{"d":"2028-02-24","ref":"2 Nephi 13:10","b":"2 Nephi","c":13,"v":10,"he":"אִמְרוּ צַדִּיק כִּי־טוֹב כִּי־פְרִי מַעַלְלֵיהֶם יֹאכֵלוּ׃","en":"Say unto the righteous that it is well with them; for they shall eat the fruit of their doings."},{"d":"2028-02-25","ref":"2 Nephi 15:20","b":"2 Nephi","c":15,"v":20,"he":"הוֹי הָאֹמְרִים לָרַע טוֹב וְלַטּוֹב רָע שָׂמִים חֹשֶׁךְ לְאוֹר וְאוֹר לְחֹשֶׁךְ שָׂמִים מַר לְמָתוֹק וּמָתוֹק לְמָר׃","en":"Wo unto them that call evil good, and good evil, that put darkness for light, and light for darkness, that put bitter for sweet, and sweet for bitter!"},{"d":"2028-02-26","ref":"2 Nephi 16:10","b":"2 Nephi","c":16,"v":10,"he":"הַשְׁמֵן לֵב־הָעָם הַזֶּה וְאׇזְנָיו הַכְבֵּד וְעֵינָיו הָשַׁע פֶּן־יִרְאֶה בְעֵינָיו וּבְאׇזְנָיו יִשְׁמָע וּלְבָבוֹ יָבִין וָשָׁב וְרָפָא לוֹ׃","en":"Make the heart of this people fat, and make their ears heavy, and shut their eyes—lest they see with their eyes, and hear with their ears, and understand with their heart, and be converted and be healed."},{"d":"2028-02-27","ref":"2 Nephi 18:14","b":"2 Nephi","c":18,"v":14,"he":"וְהָיָה לְמִקְדָּשׁ וּלְאֶבֶן נֶגֶף וּלְצוּר מִכְשׁוֹל לִשְׁנֵי בָתֵּי יִשְׂרָאֵל לְפַח וּלְמוֹקֵשׁ לְיוֹשֵׁב יְרוּשָׁלָיִם׃","en":"And he shall be for a sanctuary; but for a stone of stumbling, and for a rock of offense to both the houses of Israel, for a gin and a snare to the inhabitants of Jerusalem."}]});
